<!doctype html><html><head><meta charset="utf-8"><title>Party Statement</title><style>@page{size:A4 portrait;margin:8mm 8mm 10mm}*{box-sizing:border-box}body{font:8px Arial;color:#182536;margin:0}.et-ps-company-band,.et-ps-party-band{display:flex;justify-content:space-between;border-bottom:2px solid #182536;padding-bottom:5px;margin-bottom:6px}.et-ps-party-band{border-bottom:1px solid #182536}.et-ps-company{display:flex;gap:6px;align-items:center}.et-ps-company img{width:32px;height:32px}.et-ps-company strong,.et-ps-company small,.et-ps-party-band span{display:block}.et-ps-meta,.et-ps-report-identity{text-align:right}.et-ps-report-identity h2{font-size:12px;margin:0 0 2px}.et-ps-meta p,.et-ps-report-identity p{margin:1px 0}.et-ps-ledger-table{width:100%;max-width:100%;table-layout:fixed;border-collapse:collapse;font-size:8px}.et-ps-ledger-table th,.et-ps-ledger-table td{border:.7pt solid #000;padding:2px 3px;text-align:left;vertical-align:top;white-space:nowrap}.et-ps-ledger-table th{background:#edf3f9;print-color-adjust:exact;-webkit-print-color-adjust:exact}.et-ps-ledger-table th:nth-last-child(-n+3),.et-ps-ledger-table td:nth-last-child(-n+3){text-align:right}.et-ps-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:7px}.et-ps-summary>div{border:.7pt solid #000;padding:3px}.et-ps-summary strong,.et-ps-summary span{display:block}.et-ps-caption{text-align:right;margin:4px 0 0}col:nth-child(1){width:8%}col:nth-child(2){width:6%}col:nth-child(3){width:10%}col:nth-child(4){width:12%}col:nth-child(5){width:13%}col:nth-child(6){width:21%}col:nth-child(7){width:10%}col:nth-child(8){width:10%}col:nth-child(9){width:10%}</style></head><body>@include('accounting.party-statement._document-header')<table class="et-ps-ledger-table"><colgroup><col><col><col><col><col><col><col><col><col></colgroup><thead><tr><th>Date</th><th>Type</th><th>Invoice / Ref.</th><th>Passenger / Group</th><th>Service Ref.</th><th>Sector / Description</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>@foreach($statement['rows'] as $row)<tr><td>{{ $row['date'] }}</td><td>{{ $row['type'] }}</td><td>{{ $row['reference'] ?: '—' }}</td><td>{{ $row['party'] }}</td><td>{{ $row['service_ref'] }}</td><td>{{ $row['description'] }}</td><td>{{ $row['debit'] === null ? '' : number_format($row['debit'],2) }}</td><td>{{ $row['credit'] === null ? '' : number_format($row['credit'],2) }}</td><td>{{ number_format(abs($row['balance']),2) }} {{ $row['balance'] < 0 ? 'Cr' : 'Dr' }}</td></tr>@endforeach</tbody></table><div class="et-ps-summary"><div><strong>Opening Balance</strong><span>PKR {{ number_format(abs($statement['opening']),2) }}</span></div><div><strong>Total Debit</strong><span>PKR {{ number_format($statement['total_debit'],2) }}</span></div><div><strong>Total Credit</strong><span>PKR {{ number_format($statement['total_credit'],2) }}</span></div><div><strong>Closing Balance</strong><span>PKR {{ number_format(abs($statement['closing']),2) }} {{ $statement['closing_side'] }}</span></div></div><p class="et-ps-caption">Closing Balance Nature: {{ $statement['caption'] }}</p></body></html>
